function output<T>(maxChars: number, build: (n: number) => T): T {
  const fitted = fitSerializedEnvelope(build, { maxChars });
  if (!fitted) throw new OutputBudgetExceededError();
  return fitted.value as T;
}

export function boundedJsonFailure({ maxChars, maxBytes }: { maxChars: number; maxBytes: number }) {
  return JSON.stringify({ error: { code: 'output_budget', maxChars, maxBytes } });
}

it('rejects oversized envelopes', () => {
  expect(fitSerializedEnvelope(() => huge, { maxChars: 32 })).toBeNull();
});

export function fitSerializedEnvelope(build: (used: number) => unknown, { maxChars }: { maxChars: number }) {
  const value = build(0);
  const serialized = JSON.stringify(value);
  if (serialized.length > maxChars) return null;
  return { value };
}

