export function contentSnippet(content: string, terms: string[]) {
  return { text: content.slice(0, CONTENT_SNIPPET_CHARS), truncated: content.length > CONTENT_SNIPPET_CHARS };
}

export function scoreMemorySearch(memory: MemoryMetadata, content: string, terms: string[]) {
  const hay = `${memory.title}\n${content}`.toLowerCase();
  return terms.reduce((n, t) => n + (hay.includes(t) ? 1 : 0), 0);
}

export function rankMemorySearchResults(results: ScopedMemorySearchResult[]) {
  return [...results].sort((a, b) => b.score - a.score);
}

export function queryTerms(query: string): string[] {
  return query.split(/\s+/).filter(Boolean);
}

